int setsize (unsigned long a, unsigned int *bsize, unsigned int *csize, unsigned int *dsize) { int ssize = 0; unsigned long esize = 1024; unsigned long tsize = 62; unsigned long tmin = esize * tsize; unsigned long tmax = a / tmin; if (a % tmin != 0) { tmax++; tmin = esize * tmax; tsize = a / tmin; if (a % tmin != 0) { tsize++; tmin = tmax * tsize; esize = a / tmin; } } if (esize == 0) ssize = -1; *bsize = esize; *dsize = tsize; *csize = tmax; return ssize; }